select 'odi', 'Oswestry Disability Index (ODI)', null, 'odi', '{en}', true, 'standard', '{"en": {"title": "Oswestry Disability Index", "timeframe": "Please select the ONE statement in each section that best describes your condition today.", "items": [{"id": "odi_1", "text": "Pain intensity", "options": [{"value": 0, "label": "I have no pain at the moment"}, {"value": 1, "label": "The pain is very mild at the moment"}, {"value": 2, "label": "The pain is moderate at the moment"}, {"value": 3, "label": "The pain is fairly severe at the moment"}, {"value": 4, "label": "The pain is very severe at the moment"}, {"value": 5, "label": "The pain is the worst imaginable at the moment"}]}, {"id": "odi_2", "text": "Personal care (washing, dressing, etc.)", "options": [{"value": 0, "label": "I can look after myself normally and this does not cause extra pain"}, {"value": 1, "label": "I can look after myself normally but it is very painful"}, {"value": 2, "label": "It is painful to look after myself and I am slow and careful"}, {"value": 3, "label": "I need some help but can manage most of my personal care"}, {"value": 4, "label": "I need help every day in most aspects of self care"}, {"value": 5, "label": "I do not get dressed, wash with difficulty and stay in bed"}]}, {"id": "odi_3", "text": "Lifting", "options": [{"value": 0, "label": "I can lift heavy weights without extra pain"}, {"value": 1, "label": "I can lift heavy weights but it gives extra pain"}, {"value": 2, "label": "Pain prevents me from lifting heavy weights off the floor, but I can manage if they are conveniently positioned"}, {"value": 3, "label": "Pain prevents me from lifting heavy weights but I can manage light to medium weights if they are conveniently positioned"}, {"value": 4, "label": "I can lift only very light weights"}, {"value": 5, "label": "I cannot lift or carry anything"}]}, {"id": "odi_4", "text": "Walking", "options": [{"value": 0, "label": "Pain does not prevent me walking any distance"}, {"value": 1, "label": "Pain prevents me walking more than 1 mile"}, {"value": 2, "label": "Pain prevents me walking more than 0.5 mile"}, {"value": 3, "label": "Pain prevents me walking more than 0.25 mile"}, {"value": 4, "label": "I can only walk using a stick or crutches"}, {"value": 5, "label": "I am in bed most of the time and have to crawl to the toilet"}]}, {"id": "odi_5", "text": "Sitting", "options": [{"value": 0, "label": "I can sit in any chair as long as I like"}, {"value": 1, "label": "I can only sit in my favourite chair as long as I like"}, {"value": 2, "label": "Pain prevents me from sitting more than 1 hour"}, {"value": 3, "label": "Pain prevents me from sitting more than 30 minutes"}, {"value": 4, "label": "Pain prevents me from sitting more than 10 minutes"}, {"value": 5, "label": "Pain prevents me from sitting at all"}]}, {"id": "odi_6", "text": "Standing", "options": [{"value": 0, "label": "I can stand as long as I want without extra pain"}, {"value": 1, "label": "I can stand as long as I want but it gives me extra pain"}, {"value": 2, "label": "Pain prevents me standing for more than 1 hour"}, {"value": 3, "label": "Pain prevents me standing for more than 30 minutes"}, {"value": 4, "label": "Pain prevents me standing for more than 10 minutes"}, {"value": 5, "label": "Pain prevents me from standing at all"}]}, {"id": "odi_7", "text": "Sleeping", "options": [{"value": 0, "label": "My sleep is never disturbed by pain"}, {"value": 1, "label": "My sleep is occasionally disturbed by pain"}, {"value": 2, "label": "Because of pain I have less than 6 hours sleep"}, {"value": 3, "label": "Because of pain I have less than 4 hours sleep"}, {"value": 4, "label": "Because of pain I have less than 2 hours sleep"}, {"value": 5, "label": "Pain prevents me from sleeping at all"}]}, {"id": "odi_8", "text": "Sex life (if applicable)", "options": [{"value": 0, "label": "My sex life is normal and causes no extra pain"}, {"value": 1, "label": "My sex life is normal but causes some extra pain"}, {"value": 2, "label": "My sex life is nearly normal but is very painful"}, {"value": 3, "label": "My sex life is severely restricted by pain"}, {"value": 4, "label": "My sex life is nearly absent because of pain"}, {"value": 5, "label": "Pain prevents any sex life at all"}]}, {"id": "odi_9", "text": "Social life", "options": [{"value": 0, "label": "My social life is normal and causes me no extra pain"}, {"value": 1, "label": "My social life is normal but increases the degree of pain"}, {"value": 2, "label": "Pain has no significant effect on my social life apart from limiting my more energetic interests"}, {"value": 3, "label": "Pain has restricted my social life and I do not go out as often"}, {"value": 4, "label": "Pain has restricted my social life to my home"}, {"value": 5, "label": "I have no social life because of pain"}]}, {"id": "odi_10", "text": "Travelling", "options": [{"value": 0, "label": "I can travel anywhere without pain"}, {"value": 1, "label": "I can travel anywhere but it gives extra pain"}, {"value": 2, "label": "Pain is bad but I can manage journeys over 2 hours"}, {"value": 3, "label": "Pain restricts me to journeys of less than 1 hour"}, {"value": 4, "label": "Pain restricts me to short necessary journeys under 30 minutes"}, {"value": 5, "label": "Pain prevents me from travelling except to receive treatment"}]}], "options": []}}'::jsonb
where not exists (select 1 from public.instruments where scoring_config_key = 'odi');

