ons": [{"value": 0, "label": "I have no trouble sleeping"}, {"value": 1, "label": "My sleep is slightly disturbed (less than 1 hr sleepless)"}, {"value": 2, "label": "My sleep is mildly disturbed (1-2 hrs sleepless)"}, {"value": 3, "label": "My sleep is moderately disturbed (2-3 hrs sleepless)"}, {"value": 4, "label": "My sleep is greatly disturbed (3-5 hrs sleepless)"}, {"value": 5, "label": "My sleep is completely disturbed (5-7 hrs sleepless)"}]}, {"id": "ndi_10", "text": "Recreation", "options": [{"value": 0, "label": "I am able to engage in all my recreation activities with no neck pain"}, {"value": 1, "label": "I am able to engage in all my recreation activities with some neck pain"}, {"value": 2, "label": "I can engage in most but not all of my usual recreation activities because of neck pain"}, {"value": 3, "label": "I can engage in only a few of my usual recreation activities because of pain"}, {"value": 4, "label": "I can hardly engage in any recreation activities because of pain"}, {"value": 5, "label": "I cannot engage in any recreation activities at all"}]}], "options": []}}'::jsonb
