select 'lefs', 'Lower Extremity Functional Scale (LEFS)', null, 'lefs', '{en}', true, 'standard', '{"en": {"title": "Lower Extremity Functional Scale", "timeframe": "Today, do you or would you have any difficulty at all with the following activities?", "items": [{"id": "lefs_1", "text": "Any of your usual work, housework, or school activities"}, {"id": "lefs_2", "text": "Your usual hobbies, recreational or sporting activities"}, {"id": "lefs_3", "text": "Getting into or out of the bath"}, {"id": "lefs_4", "text": "Walking between rooms"}, {"id": "lefs_5", "text": "Putting on your shoes or socks"}, {"id": "lefs_6", "text": "Squatting"}, {"id": "lefs_7", "text": "Lifting an object, like a bag of groceries from the floor"}, {"id": "lefs_8", "text": "Performing light activities around your home"}, {"id": "lefs_9", "text": "Performing heavy activities around your home"}, {"id": "lefs_10", "text": "Getting into or out of a car"}, {"id": "lefs_11", "text": "Walking 2 blocks"}, {"id": "lefs_12", "text": "Walking a mile"}, {"id": "lefs_13", "text": "Going up or down 10 stairs (about 1 flight of stairs)"}, {"id": "lefs_14", "text": "Standing for 1 hour"}, {"id": "lefs_15", "text": "Sitting for 1 hour"}, {"id": "lefs_16", "text": "Running on even ground"}, {"id": "lefs_17", "text": "Running on uneven ground"}, {"id": "lefs_18", "text": "Making sharp turns while running fast"}, {"id": "lefs_19", "text": "Hopping"}, {"id": "lefs_20", "text": "Rolling over in bed"}], "options": [{"value": 0, "label": "Extreme difficulty or unable to perform activity"}, {"value": 1, "label": "Quite a bit of difficulty"}, {"value": 2, "label": "Moderate difficulty"}, {"value": 3, "label": "A little bit of difficulty"}, {"value": 4, "label": "No difficulty"}]}}'::jsonb
