select 'haq_di', 'Health Assessment Questionnaire (HAQ-DI)', null, 'haq_di', '{en}', true, 'standard', '{"en": {"title": "Health Assessment Questionnaire", "timeframe": "Please indicate the response which best describes your usual abilities OVER THE PAST WEEK.", "items": [{"id": "haq_di_1", "text": "Are you able to dress yourself, including tying shoelaces and doing buttons?"}, {"id": "haq_di_2", "text": "Are you able to shampoo your hair?"}, {"id": "haq_di_3", "text": "Are you able to stand up from a straight chair?"}, {"id": "haq_di_4", "text": "Are you able to get in and out of bed?"}, {"id": "haq_di_5", "text": "Are you able to cut your meat?"}, {"id": "haq_di_6", "text": "Are you able to lift a full cup or glass to your mouth?"}, {"id": "haq_di_7", "text": "Are you able to open a new milk carton?"}, {"id": "haq_di_8", "text": "Are you able to walk outdoors on flat ground?"}, {"id": "haq_di_9", "text": "Are you able to climb up five steps?"}, {"id": "haq_di_10", "text": "Are you able to wash and dry your entire body?"}, {"id": "haq_di_11", "text": "Are you able to take a tub bath?"}, {"id": "haq_di_12", "text": "Are you able to get on and off the toilet?"}, {"id": "haq_di_13", "text": "Are you able to reach and get down a 5-pound object from just above your head?"}, {"id": "haq_di_14", "text": "Are you able to bend down to pick up clothing from the floor?"}, {"id": "haq_di_15", "text": "Are you able to open car doors?"}, {"id": "haq_di_16", "text": "Are you able to open jars which have been previously opened?"}, {"id": "haq_di_17", "text": "Are you able to turn faucets on and off?"}, {"id": "haq_di_18", "text": "Are you able to run errands and shop?"}, {"id": "haq_di_19", "text": "Are you able to get in and out of a car?"}, {"id": "haq_di_20", "text": "Are you able to do chores such as vacuuming or yard work?"}], "options": [{"value": 0, "label": "Without any difficulty"}, {"value": 1, "label": "With some difficulty"}, {"value": 2, "label": "With much difficulty"}, {"value": 3, "label": "Unable to do"}]}}'::jsonb
where not exists (select 1 from public.instruments where scoring_config_key = 'haq_di');

