insert into public.instruments (code, name, version, scoring_config_key, languages, is_active, type, questions)
select 'uw_pain', 'UW Concerns About Pain (UW-CAP)', null, 'uw_pain', '{en,es}', true, 'standard', '{"en": {"title": "UW Concerns About Pain", "timeframe": "In the past 7 days, how often did you have each of the following thoughts when you were in pain?", "items": [{"id": "uw_pain_1", "text": "My pain is more than I can manage."}, {"id": "uw_pain_2", "text": "Because of my pain, I will never be happy again."}, {"id": "uw_pain_3", "text": "Because of my pain, my life is terrible."}, {"id": "uw_pain_4", "text": "My life will only get worse because of my pain."}, {"id": "uw_pain_5", "text": "Did you keep thinking about how much it hurts?"}, {"id": "uw_pain_6", "text": "Did you have trouble thinking of anything other than your pain?"}], "options": [{"value": 1, "label": "Never"}, {"value": 2, "label": "Rarely"}, {"value": 3, "label": "Sometimes"}, {"value": 4, "label": "Often"}, {"value": 5, "label": "Always"}]}, "es": {"title": "Preocupaciones sobre el dolor (UW-CAP)", "timeframe": "En los \u00faltimos 7 d\u00edas, \u00bfcon qu\u00e9 frecuencia tuvo los siguientes pensamientos cuando sent\u00eda dolor?", "items": [{"id": "uw_pain_1", "text": "Mi dolor es m\u00e1s de lo que puedo manejar."}, {"id": "uw_pain_2", "text": "A causa de mi dolor, nunca volver\u00e9 a ser feliz."}, {"id": "uw_pain_3", "text": "A causa de mi dolor, mi vida es terrible."}, {"id": "uw_pain_4", "text": "Mi vida solo empeorar\u00e1 por mi dolor."}, {"id": "uw_pain_5", "text": "\u00bfPens\u00f3 constantemente en cu\u00e1nto le dol\u00eda?"}, {"id": "uw_pain_6", "text": "\u00bfTuvo dificultad para pensar en algo que no fuera su dolor?"}], "options": [{"value": 1, "label": "Nunca"}, {"value": 2, "label": "Raramente"}, {"value": 3, "label": "A veces"}, {"value": 4, "label": "Frecuentemente"}, {"value": 5, "label": "Siempre"}]}}'::jsonb
where not exists (select 1 from public.instruments where scoring_config_key = 'uw_pain');

